import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import { Button } from './button'
import styles from './empty.module.scss'

export interface EmptyProps {
  icon?: ReactNode
  title: string
  description?: string
  action?: { label: string; onClick: () => void; className?: string }
  className?: string
  iconClassName?: string
  titleClassName?: string
  descriptionClassName?: string
}

export function Empty({
  icon,
  title,
  description,
  action,
  className,
  iconClassName,
  titleClassName,
  descriptionClassName,
}: EmptyProps) {
  return (
    <div className={cx(styles.root, className)}>
      {icon ? (
        <div className={cx(styles.icon, iconClassName)}>{icon}</div>
      ) : null}
      <h3 className={cx(styles.title, titleClassName)}>{title}</h3>
      {description ? (
        <p className={cx(styles.description, descriptionClassName)}>
          {description}
        </p>
      ) : null}
      {action ? (
        <Button
          className={cx(styles.action, action.className)}
          size="sm"
          onClick={action.onClick}
        >
          {action.label}
        </Button>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: vz.space(12) vz.space(6);
  border: 1px dashed vz.color('border');
  border-radius: vz.radius('2xl');
  background: vz.color('muted', 0.3);
  text-align: center;
}

.icon {
  display: inline-flex;
  margin-bottom: vz.space(3);
  color: vz.color('muted-foreground');

  svg {
    @include vz.icon(6);
  }
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  max-width: 24rem;
  margin: vz.space(1) 0 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

.action {
  margin-top: vz.space(4);
}
